__ht__function(json, dm, view, datas) {// ===== 获取 GraphView 和数据模型 =====
var view = graphView.getView();
var dm = graphView.dm();
//滚动条不可见
graphView.setScrollBarVisible(false);
//跟踪区域
let follow = graphView.dm().getDataByTag('follow');
var followcode = "";
//料位号（行号）
let steelnum = graphView.dm().getDataByTag('steelnum');
//物料号（钢坯号）
let steelcode = graphView.dm().getDataByTag('steelcode');
// 冷床属性字段定义
const attrcold = ['rolltype1', 'rollnum1', 'rolltype2', 'rollnum2', 'rollcolor'];
// 链条小车字段定义
const attrLine = ['rollnum', 'rollPieceID', "linetype", 'rollcolor'];
// 剪前辊道字段定义
const attrRoll = ['rollnum', 'rollPieceID', 'rollcolor'];
// 定义收集节点的通用函数
function collectNodes(prefix, maxCount, targetArray) {
    for (let i = 1; i <= maxCount; i++) {
        const tag = `${prefix}-${i}`;
        const node = dm.getDataByTag(tag);
        if (node) {
            targetArray.push(node);
        }
    }
}

// 初始化收集数组
const eighttable = [];
const ninetable = [];
const tentable = [];
const coldtable = [];
const line30 = [];
const line60 = [];
const roll30 = [];
const roll60 = [];
const befortable = [];
const staytable = [];
const cptable = [];
let rolltable30 = graphView.dm().getDataByTag('rolltable30');
let rolltable60 = graphView.dm().getDataByTag('rolltable60');
let linetable30 = graphView.dm().getDataByTag('linetable30');
let linetable60 = graphView.dm().getDataByTag('linetable60');
// 使用通用函数收集各部分节点
collectNodes('eight', 50, eighttable);
collectNodes('nine', 50, ninetable);
collectNodes('ten', 50, tentable);
// 收集动辊节点
collectNodes('befor', 20, befortable);

// 收集暂存钢节点
collectNodes('stay', 20, staytable);

// 收集收集斗节点
collectNodes('cp', 20, cptable);

//冷床 链条小车 剪前辊道
collectNodes('cold', 50, coldtable);
collectNodes('b', 100, line30);
collectNodes('a', 100, line60);
collectNodes('c', 100, roll30);
collectNodes('roll', 100, roll60);
var allTables = [
    ...eighttable,
    ...ninetable,
    ...tentable,
    ...coldtable,
    ...line30,
    ...line60,
    ...roll30,
    ...roll60,
    ...befortable,
    ...staytable,
];
// rollnum 区间映射表
const rollMap = [
    { max: 30, list: roll30 },
    { max: 60, list: roll60 }
];

// linenum 区间映射表
const lineMap = [
    { max: 30, list: line30 },
    { max: 60, list: line60 }
];
// ===== 监听数据变化 =====
var isUpdating = false;

dm.addDataPropertyChangeListener(function (e) {
    //定尺设定
    if (e.property === 'a:CALCUTLEN') {
        console.log('📥 收到 CALCUTLEN 数据：', e.newValue);
        const targetList = e.newValue;
        let table = graphView.dm().getDataByTag('CALCUTLEN');
        let table1 = graphView.dm().getDataByTag('table1');
        let table2 = graphView.dm().getDataByTag('table2');
        // 映射字段
        const keys = ["Material", "type", "position", "actual_value", "range", "confirm", "time"];

        // 只处理前两位
        const converted = targetList.slice(0, 2).map(arr =>
        keys.reduce((obj, key, index) => {
            obj[key] = arr[index] || "";
            return obj;
        }, {})
        );
        table.a('ht.dataSource', converted);
        table1.a('ht.value', targetList[2][0]);
        table2.a('ht.value', targetList[2][1]);
    }
    //班组信息标签
    if (e.property === 'a:group') {
        const group = e.newValue;
        const groupMap = {
        'A': '甲班',
        'B': '乙班',
        'C': '丙班',
        'D': '丁班'
        };

        const className = groupMap[group] || '未知班级';
        let groupNode = graphView.dm().getDataByTag('班组');
        groupNode.s('text', className);
        console.log('📥 收到 group 数据：', e.newValue);
    }
    // 通用节点处理函数
    function handleAreaNodes(e, areaNodes, areaPrefix) {
        const targetList = e.newValue;
        console.log(`新接收到的 ${areaNodes.name}：`, targetList);
        const batchList = e.newValue;
        
        const idTextMap = new Map();
        
        // 构建ID-文本映射
        batchList.forEach(([aText, bText], i) => {
            const aId = i * 2 + 1;
            const bId = i * 2 + 2;
            
            if (aText && aText.trim() !== "") {
                idTextMap.set(aId, aText);
            }
            if (bText && bText.trim() !== "") {
                idTextMap.set(bId, bText);
            }
        });
        
        // 遍历节点并更新
        areaNodes.forEach(node => {
            const tag = node.getTag();
            const match = tag.match(new RegExp(`^${areaPrefix}-(\\d+)$`));
            if (!match) return;
            
            const id = parseInt(match[1]);
            if (idTextMap.has(id)) {
                node.a('rollPieceID', idTextMap.get(id));
                node.s('2d.visible', true);
            } else {
                node.s('2d.visible', false);
            }
        });
    }

    // 8区节点处理
    if (e.property === 'a:eight') {
        handleAreaNodes(e, eighttable, 'eight');
    }

    // 9区节点处理
    if (e.property === 'a:nine') {
        handleAreaNodes(e, ninetable, 'nine');
    }

    // 10区节点处理
    if (e.property === 'a:ten') {
        handleAreaNodes(e, tentable, 'ten');
    }

    // 收集斗节点
    if (e.property === 'a:CollectHopper') {
        const targetList = e.newValue;
        console.log('新接收到的 CollectHopper', targetList);
        // 注意：此时 textList 是一维数组，格式如 [ "批号", "批号", ...]
        const textList = e.newValue;  

        cptable.forEach(node => {
            const tag = node.getTag(); // 例如 "stay-1"
            const match = tag.match(/^cp-(\d+)$/);
            if (!match) return;

            const id = parseInt(match[1]); // 获取数字部分（如 1、2、3...）
            // 关键修改：直接从一维数组中取值，无需再取子数组的第0项
            const text = textList[id - 1] ? textList[id - 1].trim() : ""; // 处理undefined并提前去空格

            if (text !== "") { // 因为已提前trim，直接判断非空即可
                node.a('rollPieceID', text);
                node.s('2d.visible', true);
            } else {
                node.s('2d.visible', false);
            }
        });
    }

    //暂存区节点
    if (e.property === 'a:staytable') {
        const targetList = e.newValue;
        console.log('新接收到的 staytable：', targetList);
        // 注意：此时 textList 是二维数组，格式如 [[ "批号" ], [ "批号" ], ...]
        const textList = e.newValue;  

        staytable.forEach(node => {
            const tag = node.getTag(); // 例如 "stay-1"
            const match = tag.match(/^stay-(\d+)$/);
            if (!match) return;

            const id = parseInt(match[1]); // 获取数字部分（如 1、2、3...）
            // 关键修改：先取二维数组的外层元素（子数组），再取子数组的第 0 项（实际批号文本）
            const subArr = textList[id - 1]; 
            const text = subArr ? subArr[0] : ""; // 处理可能的 undefined 情况

            if (text && text.trim() !== "") {
                node.a('rollPieceID', text);
                node.s('2d.visible', true);
            } else {
                node.s('2d.visible', false);
            }
        });
    }

    // 剪前辊道区节点
    if (e.property === 'a:backtable') {
        const targetList = e.newValue;
        console.log('新接收到的 backtable：', targetList);
        const textList = e.newValue;  // 格式：[[], [], ["B12506537"], ...]

        befortable.forEach(node => {
            const tag = node.getTag(); // 例如 "befor-1"
            const match = tag.match(/^befor-(\d+)$/);
            if (!match) return;

            const id = parseInt(match[1]); // 获取数字部分
            const item = textList[id]; // 获取对应索引的项

            // 安全提取文本值（处理嵌套数组）
            let text = '';
            if (Array.isArray(item) && item.length > 0) {
                text = item[0]; // 取数组的第一个元素
            }

            // 安全处理文本值
            if (typeof text === 'string' && text.trim() !== "") {
                node.a('rollPieceID', text.trim()); // 应用 trim() 处理
                node.s('2d.visible', true);
            } else {
                node.s('2d.visible', false);
            }
        });
    }



    //文本信息过滤
    if (isUpdating) return;
    if (e.property === 's:text') {
        var d = e.data;
        var textValue = d.s('text');
        var numericValue = parseFloat(textValue);

        isUpdating = true;
        if (!isNaN(numericValue)) {
            const displayName = d.getDisplayName();
            let value = numericValue;
            let expr = '';
            let decimals = 2;  // 默认保留2位小数
            let name = '';     // 存储名称部分

            if (displayName) {
                // 1️⃣ 匹配 "名称+(内容)" 格式
                const mainMatch = displayName.match(/^(.+?)\+\((.+)\)$/);
                
                if (mainMatch) {
                    name = mainMatch[1];  // 提取名称
                    const content = mainMatch[2];  // 括号内的内容
                    
                    // 2️⃣ 根据括号内的内容格式解析表达式和小数位
                    // 格式1：表达式+小数位 (如 "+100'2'")
                    const exprWithDecimalMatch = content.match(/^(.+)'(\d+)'$/);
                    if (exprWithDecimalMatch) {
                        expr = exprWithDecimalMatch[1];
                        decimals = parseInt(exprWithDecimalMatch[2], 10);
                    }
                    // 格式2：仅小数位 (如 "'3'" 或 "3")
                    else if (/^'?\d+'?$/.test(content)) {
                        decimals = parseInt(content.replace(/'/g, ''), 10);
                    }
                    // 格式3：仅表达式 (如 "+50")
                    else {
                        expr = content;
                    }
                }
                // 未匹配到 "名称+(内容)" 格式（兼容旧格式）
                else {
                    // 保持原有逻辑不变
                    const exprWithDecimalMatch = displayName.match(/^(.+)'(\d+)'$/);
                    if (exprWithDecimalMatch) {
                        expr = exprWithDecimalMatch[1];
                        decimals = parseInt(exprWithDecimalMatch[2], 10);
                    }
                    else if (/^'?\d+'?$/.test(displayName)) {
                        decimals = parseInt(displayName.replace(/'/g, ''), 10);
                    }
                    else {
                        expr = displayName;
                    }
                }
            }

            // 执行表达式计算（保持原有逻辑不变）
            if (expr) {
                try {
                    const fn = new Function('v', `return v ${expr};`);
                    value = fn(numericValue);
                } catch (e) {
                    console.warn('表达式执行失败：', expr, e);
                }
            }

            // 应用小数位控制（保持原有逻辑不变）
            d.s('text', value.toFixed(decimals));
        }
        isUpdating = false;
    }

    // 链条小车
    if(e.property === 'a:linetable'){
        const targetList = e.newValue;
        console.log('新接收到的 linetable：', targetList);

                // 初始化计数器：第三个元素为0/1的数量（仅在第2位非空时统计）
        let countThirdIs0 = 0; 
        let countThirdIs1 = 0; 
        let linecount = graphView.dm().getDataByTag('链条计数');
        let carcount = graphView.dm().getDataByTag('小车计数');

        if (Array.isArray(targetList)) {
            targetList.forEach(subArr => {
                // 1. 基础校验：子数组是数组
                if (Array.isArray(subArr)) {
                    // 2. 校验第2位（下标1）不为空（排除undefined/null/空白字符串）
                    const secondVal = subArr[1];
                    const isSecondValid = secondVal !== undefined && 
                                        secondVal !== null && 
                                        !Number.isNaN(secondVal) && 
                                        secondVal.toString().trim() !== '';

                    // 3. 第2位非空时，再判断第3位（下标2）的值
                    if (isSecondValid) {
                        const thirdVal = subArr[2];
                        // 兼容字符串/数字类型的0/1
                        if (thirdVal === '0' || thirdVal === 0) {
                            countThirdIs0++;
                        } else if (thirdVal === '1' || thirdVal === 1) {
                            countThirdIs1++;
                        }
                    }
                }
            });
        }

        linecount.s('text',countThirdIs0);
        carcount.s('text',countThirdIs1);
        // 输出计数结果
        console.log('第2位非空时，第三个元素为0的数量：', countThirdIs0);
        console.log('第2位非空时，第三个元素为1的数量：', countThirdIs1);
        
        // 查找最后一个 rollPieceID 不为空的行
        let lastNonEmptyRowIndex = -1;
        for (let i = targetList.length - 1; i >= 0; i--) {
            const row = targetList[i];
            if (Array.isArray(row) && row[1] !== null && row[1] !== '') {
                lastNonEmptyRowIndex = i;
                break;
            }
        }
        
        // 如果没有找到非空的 rollPieceID 行，则隐藏所有线条
        if (lastNonEmptyRowIndex === -1) {
            linetable30.s('2d.visible', false); // 设置 linetable30 不可见
            linetable60.s('2d.visible', false); // 设置 linetable60 不可见
            console.log('所有行的 rollPieceID 都为空，已隐藏所有线条');
            return; // 直接返回，不需要继续处理
        }
        
        // 处理有非空行的情况
        const lastRow = targetList[lastNonEmptyRowIndex];
        const rollnum = lastRow[0];

        // 查找对应的 line 数组
        const mapping = lineMap.find(m => rollnum <= m.max);
        if (mapping) {
            const targetNodes = mapping.list;
            // 根据当前的映射，设置可见性
            if (mapping.list === line30) {
                linetable30.s('2d.visible', true);  // 设置 linetable30 可见
                linetable60.s('2d.visible', false); // 设置 linetable60 不可见
                console.log('只设置 line30 可见');
            } else if (mapping.list === line60) {
                linetable30.s('2d.visible', false); // 设置 linetable30 不可见
                linetable60.s('2d.visible', true);  // 设置 linetable60 可见
                console.log('只设置 line60 可见');
            } else {
                linetable30.s('2d.visible', false); // 设置 linetable30 不可见
                linetable60.s('2d.visible', false); // 设置 linetable60 不可见
            }
            
            targetNodes.forEach((node, index) => {
                const values = targetList[index];
                // 数据行校验
                if (Array.isArray(values) && values.length >= attrLine.length) {
                    attrLine.forEach((attr, i) => {
                        node.a(attr, values[i]);
                    });
                }
            });
            console.log(`已更新到对应 line 组：line${mapping.max}`);
        }
    }

    //剪切辊道
    if(e.property === 'a:rolltable'){
        const targetList = e.newValue;
        console.log('新接收到的 rolltable：', targetList);
        
        // 查找最后一个 rollPieceID 不为空的行
        let lastNonEmptyRowIndex = -1;
        for (let i = targetList.length - 1; i >= 0; i--) {
            const row = targetList[i];
            if (Array.isArray(row) && row[1] !== null && row[1] !== '') {
                lastNonEmptyRowIndex = i;
                break;
            }
        }
        
        // 如果没有找到非空的 rollPieceID 行，则隐藏所有线条
        if (lastNonEmptyRowIndex === -1) {
            rolltable30.s('2d.visible', false); // 设置 rolltable30 不可见
            rolltable60.s('2d.visible', false); // 设置 rolltable60 不可见
            console.log('所有行的 rollPieceID 都为空，已隐藏所有线条');
            return; // 直接返回，不需要继续处理
        }
        
        // 处理有非空行的情况
        const lastRow = targetList[lastNonEmptyRowIndex];
        const rollnum = lastRow[0];

        // 查找对应的 roll 数组
        const mapping = rollMap.find(m => rollnum <= m.max);
        if (mapping) {
            const targetNodes = mapping.list;
            // 根据当前的映射，设置可见性
            if (mapping.list === roll30) {
                rolltable30.s('2d.visible', true);  // 设置 rolltable30 可见
                rolltable60.s('2d.visible', false); // 设置 rolltable60 不可见
                console.log('只设置 roll30 可见');
            } else if (mapping.list === roll60) {
                rolltable30.s('2d.visible', false); // 设置 rolltable30 不可见
                rolltable60.s('2d.visible', true);  // 设置 rolltable60 可见
                console.log('只设置 roll60 可见');
            } else {
                rolltable30.s('2d.visible', false); // 设置 rolltable30 不可见
                rolltable60.s('2d.visible', false); // 设置 rolltable60 不可见
            }
            
            targetNodes.forEach((node, index) => {
                const values = targetList[index];
                // 数据行校验
                if (Array.isArray(values) && values.length >= attrRoll.length) {
                    attrRoll.forEach((attr, i) => {
                        node.a(attr, values[i]);
                    });
                }
            });
            console.log(`已更新到对应 roll 组：roll${mapping.max}`);
        }
    }
    
    //冷床标签信息
    if(e.property === 'a:coldtable'){
        const targetList = e.newValue;
        console.log('新接收到的 coldtable：', targetList);

        // ********** 核心计数逻辑 **********
        // 初始化计数器：统计第一个元素不为0的子数组数量
        let countNonZeroFirst = 0;
        let count = graphView.dm().getDataByTag('冷床计数');
        // 先校验 targetList 是数组，避免非数组类型遍历报错
        if (Array.isArray(targetList)) {
            targetList.forEach(subArr => {
                // 校验：子数组是数组 + 第一个元素存在 + 第一个元素不是0（兼容字符串/数字0）
                if (
                    Array.isArray(subArr) && 
                    subArr[0]!== undefined && 
                    subArr[0]!== '0' && 
                    subArr[0]!== 0
                ) {
                    countNonZeroFirst++;
                }
            });
        }
        
        // 输出计数结果（也可根据需求赋值给变量/用于后续逻辑）
        console.log('rolltable1中第一个元素不为0的数量：', countNonZeroFirst);
        count.s('text',countNonZeroFirst)
        // ********** 计数逻辑结束 **********

        // 遍历 coldTables 中的所有节点
        coldtable.forEach((f, index) => {
            if (index < targetList.length) { // 确保有对应数据
                let values = targetList[index]; // 取出该节点对应的数据行
                let rolltype1 = values[0]; // rolltype1
                let rollnum1 = values[1]; // rollnum1
                let rolltype2 = values[2]; // rolltype1
                let rollnum2 = values[3]; // rollnum2

                // 赋值给 rolltype1 指定的 RollPieceID
                if (rolltype1 === "1") {
                    f.a('r1.RollPieceID', rollnum1);
                } else if (rolltype1 === "2") {
                    f.a('r2.RollPieceID', rollnum1);
                } else if (rolltype1 === "3") {
                    f.a('r3.RollPieceID', rollnum1);
                }

                if (rolltype2 === "2") {
                    f.a('r2.RollPieceID', rollnum2);
                }

                // 继续赋值其他属性
                attrcold.forEach((attr, i) => {
                    f.a(attr, values[i]);
                });
                let rollcolor = values[4]; // rollcolor是1-4的编号
                var lineColor = ["rgb(240,225,19)", "rgb(48,242,120)","rgb(48,242,120)","rgb(48,242,120)"];
                // rollcolor 是字符串，确保转换为数字
                let colorIndex = Number(rollcolor) - 1; // 因为数组下标是从0开始
                if (colorIndex >= 0 && colorIndex < lineColor.length) {
                    let color = lineColor[colorIndex];
                    f.a('r1.lineColor', color);
                    f.a('r2.lineColor', color);
                    f.a('r3.lineColor', color);
                }
            }
        });
    }
});

    // 所有跟踪区域共有事件
    // 互斥状态变量
    let isClicked = false;
    let isPreparingClick = false;
    allTables.forEach((node, index) => {
        if (node) {
            var virtualNode = graphView.dm().getDataByTag('set'); // 弹窗节点
            let hoverTimeout, leaveTimeout;

    // 弹窗事件(type查找点击子图标)
    // 定义一个函数来处理属性的赋值
    function setVirtualNodeProperty(node, key, value) {
        if (value !== undefined && value !== null) {
            node.a(key, value);  // 使用 a() 方法赋值
            console.log(`${key} 已赋值:`, value);
        }
    }
    // 鼠标按下时，标记“准备点击”
    node.s('onMousedown', function () {
        isPreparingClick = true;
    });

    // 鼠标离开时，如果不是点击行为，延迟隐藏弹窗
    node.s('onLeave', function (event, data, view) {
        if (isClicked || isPreparingClick) return;
        clearTimeout(hoverTimeout);
        leaveTimeout = setTimeout(() => {
            virtualNode.s('2d.visible', false);
        }, 1000);
    });

    // 点击节点时，显示弹窗 + 拉取数据
    node.s('onClick', function (event, data, view) {
        isClicked = true;
        isPreparingClick = false;

        clearTimeout(hoverTimeout);
        clearTimeout(leaveTimeout);

        virtualNode.s('2d.visible', true);

        const point = graphView.getLogicalPoint(event);
        virtualNode.setPosition(point.x + 100, point.y - 100);
        //物料参数获取
        let Line = "B201";
        //物料号，钢坯号，材料号，料编号
        let RollPieceID = "";
        let nodeTag = node.getTag();
        if (nodeTag.includes('cold')) {
            if (node.a('type') == "1" || node.a('type') == "3") {
            RollPieceID = node.a('rollnum1');
        } else if (node.a('type') == "2") {
            RollPieceID = node.a('rollnum2');
        }
        }else{
            RollPieceID = node.a('rollPieceID');
        }
        let prefix = nodeTag.split('-')[0]; // 获取纯字母部分
        // 预定义前缀到结果的映射关系
        const prefixMap = {
            // 数字前缀映射
            eight: { followcode: 8, message: '走数字分支：eight' },
            nine: { followcode: 9, message: '走数字分支：nine' },
            ten: { followcode: 10, message: '走数字分支：ten' },
