let Section = row3.a('ht.value');
let ActValue = row4.a('ht.value');
let RequireValue = row5.a('ht.value');
let OccurTime = row6.a('ht.value');
let Confirmer = row7.a('ht.value');
let Weight = row8.a('ht.value');
let url = `http://180.10.10.12:9003/api/sdf/sltdatabnormal/boardcreate`;
    // 准备请求数据
const requestData = {
    "line" : Line,
    "Area" : Area,
    "Processes" : Processes,
    "SHIFT_GROUP" : SHIFT_GROUP,
    "ROLL_PLAN_NO": "0",
    "MtlNo": SlabNo.toString(),
    "AbnormalType": AbnormalType.toString(),
    "Section": Section.toString(),
    "ActValue": parseFloat(ActValue),
    "Weight": parseFloat(Weight),
    "RequireValue": parseFloat(RequireValue).toString(), // ✅
    "OccurTime": new Date(OccurTime).toISOString(), // ✅ ISO格式
    "Confirmer": Confirmer.toString()
};

// 发送PUT请求
fetch(url, {
  method: 'PUT', // 指定请求方法为PUT
  headers: {
    'Content-Type': 'application/json', // 指定请求体格式为JSON
  },
  body: JSON.stringify(requestData) // 将JavaScript对象转换为JSON字符串
})
.then(response => {
  if (!response.ok) throw new Error(`HTTP错误! 状态码: ${response.status}`);
  return response.json(); // 解析响应数据（如果返回JSON）
})
.then(data => {
  console.log('PUT请求成功:', data);
  if (data.Message) {
    showToast(data.Message);
  }
})
.catch(error => {
  console.error('PUT请求失败:', error);
  showToast('请求失败，请稍后重试');
});}

